#include <iostream>
#include <string>
#include <string_view>

class GradeBook {
public:
    void setCourseName(std::string_view name) {
        courseName = name;
    }

    [[nodiscard]] std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        // Software engineering practice: use getter internally
        std::cout << "Welcome to the grade book for\n" 
                  << getCourseName() << "!\n";
    }

private:
    std::string courseName;
};

int main() {
    GradeBook book;
    book.setCourseName("CS101 Introduction to C++ Programming");
    book.displayMessage();
    return 0;
}

#include <iostream>
#include <string>
#include <utility>

class GradeBook {
public:
    // Explicit constructor with member-initializer list
    explicit GradeBook(std::string name)
        : courseName(std::move(name)) {
        // Empty body
    }

    void setCourseName(std::string name) {
        courseName = std::move(name);
    }

    [[nodiscard]] std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" 
                  << getCourseName() << "!\n";
    }

private:
    std::string courseName;
};

int main() {
    // Create two GradeBook objects passing initial values to constructors
    GradeBook gradeBook1("CS101 Introduction to C++ Programming");
    GradeBook gradeBook2("CS102 Data Structures in C++");

    std::cout << "gradeBook1 created for course: " << gradeBook1.getCourseName() << "\n";
    std::cout << "gradeBook2 created for course: " << gradeBook2.getCourseName() << "\n";

    return 0;
}
